  .section-head h2 { font-size: 1.45rem; line-height: 1.3; letter-spacing: -0.01em; }
  .section-head h2 .zh { display: block; font-size: 0.98rem; color: var(--muted); font-weight: 600; }

  .grid {
    display: grid;
