  .col h3 { font-size: 1.06rem; margin: 1.1rem 0 0.45rem; color: var(--accent-strong); line-height: 1.4; }
  .col:first-child h3:first-of-type { margin-top: 0; }
  .col p { margin: 0.7rem 0; color: var(--text); }
