  .summary p { margin: 0; }

  /* View modes */
  body[data-view="en"] .col.zh { display: none; }
  body[data-view="zh"] .col.en { display: none; }
  body[data-view="en"] .grid,
  body[data-view="zh"] .grid { grid-template-columns: 1fr; }
  body[data-view="en"] .col, body[data-view="zh"] .col { max-width: 780px; margin: 0 auto; width: 100%; }

  /* Intro / hero content already above; small footer */
