<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>طبقات الأرض — القشرة والوشاح واللب</title>
<style>
  :root {
    --bg: #f7f2ea;
    --surface: #fffdf8;
    --surface-alt: #fbf6ec;
    --ink: #2c231a;
    --muted: #6f6152;
    --border: #e7ddc9;
    --accent: #c1571e;
    --accent-strong: #9c4213;
    --crust: #c08a4d;
    --mantle: #e07a3e;
    --outer: #d2452a;
    --inner: #f0b13e;
    --shadow: 0 4px 22px rgba(90, 60, 25, 0.10);
    --radius: 18px;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body {
    font-family: "Noto Sans Arabic", "Segoe UI", Tahoma, "DejaVu Sans", Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.9;
    min-height: 100vh;
  }

  header.hero {
    text-align: center;
    padding: 2.8rem 1.5rem 1.9rem;
    background: linear-gradient(165deg, #efe2cf 0%, var(--bg) 75%);
    border-bottom: 1px solid var(--border);
  }
  .hero-badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    color: var(--accent-strong);
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 999px;
    padding: 0.35rem 1rem;
    margin-bottom: 1.1rem;
  }
  header.hero h1 {
    font-size: clamp(2rem, 5vw, 2.9rem);
    line-height: 1.3;
    letter-spacing: -0.01em;
    font-weight: 800;
  }
  header.hero h1 .dot { color: var(--accent); }
  header.hero p.lede {
    max-width: 620px;
    margin: 0.9rem auto 0;
    color: var(--muted);
    font-size: 1.05rem;
  }

  main {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.2rem 1.4rem 2.6rem;
  }
  .stage {
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    gap: 1.5rem;
    align-items: start;
  }

  /* ---------- diagram  ---------- */
  .diagram {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    padding: 1.6rem 1.2rem 1.3rem;
    text-align: center;
  }
  .diagram h2 {
    font-size: 1rem;
    font-weight: 700;
    color: var(--muted);
    margin-bottom: 0.8rem;
    letter-spacing: 0.02em;
  }
  svg.earth { width: min(100%, 430px); height: auto; display: block; margin: 0 auto; }
  svg.earth .ring { cursor: pointer; outline: none; }
  svg.earth .ring circle {
    stroke: rgba(255, 255, 255, 0.35);
    stroke-width: 2;
    transition: filter 0.25s ease;
  }
  svg.earth .ring:hover circle,
  svg.earth .ring:focus-visible circle { filter: brightness(1.07); }
  svg.earth .ring.active circle { filter: saturate(1.18) brightness(1.05) drop-shadow(0 0 12px rgba(192, 87, 30, 0.45)); }
  svg.earth .ring:focus-visible circle { stroke: rgba(156, 66, 19, 0.85); stroke-width: 3; }
  .legend {
    margin-top: 1rem;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.55rem;
  }
  .legend button {
    font: inherit;
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--ink);
    background: var(--surface-alt);
    border: 1px solid var(--border);
    border-radius: 999px;
    padding: 0.45rem 1rem;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: all 0.18s ease;
  }
  .legend button .dot {
    width: 0.72rem; height: 0.72rem; border-radius: 50%;
    background: var(--c);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--c) 30%, transparent);
  }
  .legend button:hover { border-color: var(--accent); }
  .legend button.active {
    background: var(--ink);
    color: var(--bg);
    border-color: var(--ink);
  }
  .legend button.active .dot { box-shadow: 0 0 0 3px color-mix(in srgb, var(--c) 45%, transparent); }
  .diagram .hint {
    margin-top: 0.9rem;
    font-size: 0.8rem;
    color: var(--muted);
  }

  /* ---------- info panel  ---------- */
  .panel {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    padding: 1.6rem;
    min-height: 380px;
  }
  .panel.enter { animation: panelIn 0.38s ease both; }
  @keyframes panelIn {
    from { opacity: 0; transform: translateY(10px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  .panel-badge {
    display: inline-block;
    font-size: 0.72rem;
    font-weight: 800;
    color: var(--accent-strong);
    background: color-mix(in srgb, var(--accent) 12%, transparent);
    border-radius: 6px;
    padding: 0.22rem 0.7rem;
    margin-bottom: 0.6rem;
  }
  .panel h3 { font-size: 1.7rem; line-height: 1.35; margin-bottom: 0.15rem; }
  .panel .tagline { color: var(--muted); font-size: 0.95rem; margin-bottom: 1.1rem; }
  .stats {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.55rem;
    margin-bottom: 1.1rem;
  }
  .stat {
    background: var(--surface-alt);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 0.55rem 0.75rem;
  }
  .stat .label { display: block; font-size: 0.72rem; color: var(--muted); font-weight: 700; }
  .stat .value { display: block; font-size: 1.02rem; font-weight: 800; margin-top: 0.1rem; }
  .panel .desc { font-size: 1rem; margin-bottom: 0.85rem; }
  .panel .note {
    font-size: 0.88rem;
    color: var(--accent-strong);
    background: color-mix(in srgb, var(--accent) 9%, transparent);
    border-radius: 10px;
    padding: 0.65rem 0.85rem;
    border-right: 4px solid var(--accent);
  }

  footer {
    text-align: center;
    color: var(--muted);
    font-size: 0.82rem;
    padding: 0 1.4rem 2rem;
  }

  @media (max-width: 780px) {
    .stage { grid-template-columns: 1fr; }
    .panel { min-height: 0; }
    svg.earth { width: min(100%, 340px); }
  }
  @media (prefers-reduced-motion: reduce) {
    * { animation: none !important; transition: none !important; }
  }
</style>
</head>
