        <g class="ring" data-layer="crust" role="button" tabindex="0" aria-label="القشرة الأرضية">
          <circle cx="260" cy="260" r="208" fill="#c08a4d"/>
        </g>
        <g class="ring" data-layer="mantle" role="button" tabindex="0" aria-label="الوشاح">
          <circle cx="260" cy="260" r="182" fill="#e07a3e"/>
        </g>
        <g class="ring" data-layer="core" role="button" tabindex="0" aria-label="اللب">
          <circle cx="260" cy="260" r="118" fill="#d2452a"/>
        </g>
        <g class="ring" data-layer="core" role="button" tabindex="0" aria-label="النواة الداخلية">
          <circle cx="260" cy="260" r="56" fill="#f0b13e"/>
        </g>
      </svg>

      <div class="legend" id="legend">
        <button type="button" data-layer="crust" style="--c:#c08a4d" aria-pressed="true"><span class="dot"></span>القشرة</button>
        <button type="button" data-layer="mantle" style="--c:#e07a3e" aria-pressed="false"><span class="dot"></span>الوشاح</button>
        <button type="button" data-layer="core" style="--c:#d2452a" aria-pressed="false"><span class="dot"></span>اللب</button>
