      <p class="hint">اضغط على الطبقات في المخطط أو على القائمة بالأسفل لاستكشاف كل طبقة</p>
    </div>

    <aside class="panel enter" id="panel" aria-live="polite"></aside>

  </div>
</main>

<footer>
  تعرض مبسّط مبني على نموذجي مستندين تاريخيين · أرقام تقريبية لأغراض التوثيق
</footer>

<script>
  (function () {
    var DATA = {
      crust: {
