          { label: 'السمك', value: 'نحو 2,900 كم' },
          { label: 'العمق', value: '40 – 2,890 كم' },
          { label: 'درجة الحرارة', value: '500 – 4,000°م' },
          { label: 'التركيب', value: 'صخور قليلة الفلز (بيريدوتيت)' }
        ],
        desc: 'رغم أنه صلب من حيث التركيب، فإن الحرارة والضغط الهائلين يجعلانه يتدفق ببطء عبر الحمل الحراري. هذا التدفق هو ما يدفع الصفائح التكتونية فوقه، ويُمسك حركة جبالنا وبدائلنا.',
