fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0

    // Sub-half-second exposures: show the shutter fraction ("1/30s", "1/1000s").
    if (seconds < 0.5) {
        val denominator = (1.0 / seconds).roundToLong()
        if (denominator >= 2L) return "1/${denominator}s"
    }

    // Half-second or slower exposures: show decimal seconds ("0.5s", "2.5s", "2s").
    val tenths = (seconds * 10.0).roundToLong()
    val whole = tenths / 10
    val tenth = tenths % 10
    return if (tenth == 0L) "${whole}s" else "${whole}.${tenth}s"
}

