{"content": """"Minimal chess move generation (first pass).

Supported: normal piece movement, captures, pawn double pushes.
Not supported yet: castling, en passant, promotion, pin/check legality
(king safety and checks are NOT filtered). Pawns reaching the far rank
emit a plain UCI move like 'e7e8' (no promotion suffix). Castling-related
and clock/move-number FEN fields are ignored. Works for any valid FEN.
"""

_FILES = 'abcdefgh'
_VALID_PIECES = set('PNBRQKpnbrqk')


def _parse_square(s):
    return int(s[1]) - 1, _FILES.index(s[0])


def _square_name(r, c):
    return _FILES[c] + str(r + 1)


def _parse_fen(fen):
    parts = fen.split()
    if len(parts) < 2:
        raise ValueError('FEN needs at least a placement field and a side to move')
    placement, active = parts[0], parts[1]
    if active not in ('w', 'b'):
        raise ValueError('side to move must be "w" or "b"')

    rows = placement.split('/')
    if len(rows) != 8:
        raise ValueError('piece placement must have 8 rows')

    board = [[None] * 8 for _ in range(8)]
    for i, row in enumerate(rows):
        r = 7 - i  # FEN top row is rank 8
        c = 0
        for ch in row:
            if '1' <= ch <= '9':
                c += int(ch)
            elif ch in _VALID_PIECES:
                board[r][c] = ch
                c += 1
            else:
                raise ValueError(f'invalid piece character {ch!r}')
        if c != 8:
            raise ValueError('piece placement row does not sum to 8')
    return board, active


def _generate_moves(board, active):
    """Return UCI move strings for the side to move (no legality filtering)."""
    moves = []
    white = active == 'w'
    my = set('PNBRQK') if white else set('pnbrqk')
    enemy = set('pnbrqk') if white else set('PNBRQK')
    dr = 1 if white else -1          # pawn direction in rank index
    start_rank = 1 if white else 6   # white pawns start on rank 2 (index 1), black on rank 7 (index 6)

    for r in range(8):
        for c in range(8):
            ch = board[r][c]
            if ch is None or ch not in my:
                continue
            kind = ch.upper()
            src = _square_name(r, c)

            if kind == 'P':
                nr = r + dr
                if 0 <= nr < 8:
                    # one-square push
                    if board[nr][c] is None:
                        moves.append(src + _square_name(nr, c))
                        # double push from the starting rank
                        nr2 = r + 2 * dr
                        if r == start_rank and 0 <= nr2 < 8 and board[nr2][c] is None:
                            moves.append(src + _square_name(nr2, c))
                    # diagonal captures
                    for dc in (-1, 1):
                        nc = c + dc
                        if 0 <= nc < 8 and board[nr][nc] is not None and board[nr][nc] in enemy:
                            moves.append(src + _square_name(nr, nc))
                continue

            if kind == 'N' or kind == 'K':
                offsets = (
                    [(1, 2), (2, 1), (2, -1), (1, -2),
                     (-1, -2), (-2, -1), (-2, 1), (-1, 2)]
                    if kind == 'N'
                    else [(dr2, dc) for dr2 in (-1, 0, 1) for dc in (-1, 0, 1) if not (dr2 == 0 and dc == 0)]
                )
                for dr2, dc in offsets:
                    nr, nc = r + dr2, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] not in my:
                        moves.append(src + _square_name(nr, nc))
                continue

            # sliding pieces: B, R, Q
            if kind in ('B', 'R', 'Q'):
                dirs = []
                if kind in ('B', 'Q'):
                    dirs += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
                if kind in ('R', 'Q'):
                    dirs += [(1, 0), (-1, 0), (0, 1), (0, -1)]
                for dr2, dc in dirs:
                    nr, nc = r + dr2, c + dc
                    while 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if target is None:
                            moves.append(src + _square_name(nr, nc))
                        elif target in enemy:
                            moves.append(src + _square_name(nr, nc))
                            break
                        else:
                            break  # blocked by own piece
                        nr += dr2
                        nc += dc

    return moves


def legal_moves(fen):
    """Every move for the side to move in `fen`, in UCI notation."""
    board, active = _parse_fen(fen)
    return _generate_moves(board, active)


def _perft_board(board, active, depth):
    if depth == 0:
        return 1
    total = 0
    for mv in _generate_moves(board, active):
        r1, c1 = _parse_square(mv[:2])
        r2, c2 = _parse_square(mv[2:4])
        new_board = [row[:] for row in board]
        new_board[r2][c2] = new_board[r1][c1]
        new_board[r1][c1] = None
        next_active = 'b' if active == 'w' else 'w'
        total += _perft_board(new_board, next_active, depth - 1)
    return total


def perft(fen, depth):
    """Number of leaf nodes at `depth` plies (perft(0) == 1)."""
    if depth < 0:
        raise ValueError('depth must be >= 0')
    board, active = _parse_fen(fen)
    return _perft_board(board, active, depth)
