{"content": """"Minimal chess move generation (first pass).

Supported: normal piece movement, captures, pawn double pushes, castling.
Not supported yet: en passant, promotion, check/pin legality for normal
moves (castling itself is still checked: not out of / through / into check;
the king path must be clear). Pawns reaching the far rank emit a plain UCI
move like 'e7e8' (no promotion suffix). Clock/move-number FEN fields are
ignored. Works for any valid FEN.
"""

_FILES = 'abcdefgh'
_VALID_PIECES = set('PNBRQKpnbrqk')

_KNIGHT_OFFSETS = [(1, 2), (2, 1), (2, -1), (1, -2),
                  (-1, -2), (-2, -1), (-2, 1), (-1, 2)]
_KING_OFFSETS = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                 if not (dr == 0 and dc == 0)]
_STRAIGHT_DIRS = [(0, 1), (0, -1), (1, 0), (-1, 0)]
_DIAGONAL_DIRS = [(1, 1), (1, -1), (-1, 1), (-1, -1)]


def _parse_square(s):
    return int(s[1]) - 1, _FILES.index(s[0])


def _square_name(r, c):
    return _FILES[c] + str(r + 1)


def _parse_fen(fen):
    parts = fen.split()
    if len(parts) < 2:
        raise ValueError('FEN needs at least a placement field and a side to move')
    placement, active = parts[0], parts[1]
    if active not in ('w', 'b'):
        raise ValueError('side to move must be "w" or "b"')

    rows = placement.split('/')
    if len(rows) != 8:
        raise ValueError('piece placement must have 8 rows')

    board = [[None] * 8 for _ in range(8)]
    for i, row in enumerate(rows):
        r = 7 - i  # FEN top row is rank 8
        c = 0
        for ch in row:
            if '1' <= ch <= '9':
                c += int(ch)
            elif ch in _VALID_PIECES:
                board[r][c] = ch
                c += 1
            else:
                raise ValueError(f'invalid piece character {ch!r}')
        if c != 8:
            raise ValueError('piece placement row does not sum to 8')
    return board, active


def _parse_rights(fen):
    parts = fen.split()
    if len(parts) >= 3:
        field = parts[2]
        if field != '-':
            return set(ch for ch in field if ch in 'KQkq')
    return set()


def _attacked_by(board, r, c, enemy):
    """True if square (r, c) is attacked by any piece of color `enemy`
    ('w' or 'b') on the given board. Pinned enemy pieces still count."""
    if not (0 <= r < 8 and 0 <= c < 8):
        return False

    # enemy pawns
    if enemy == 'w':
        # a white pawn attacking (r, c) sits at (r-1, c±1)
        for dc in (-1, 1):
            nr, nc = r - 1, c + dc
            if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] == 'P':
                return True
    else:
        # a black pawn attacking (r, c) sits at (r+1, c±1)
        for dc in (-1, 1):
            nr, nc = r + 1, c + dc
            if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] == 'p':
                return True

    # enemy knights
    knight = 'N' if enemy == 'w' else 'n'
    for dr, dc in _KNIGHT_OFFSETS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] == knight:
            return True

    # enemy king (adjacent squares)
    king = 'K' if enemy == 'w' else 'k'
    for dr, dc in _KING_OFFSETS:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] == king:
            return True

    # sliding pieces, scanned backwards from the target square
    if enemy == 'w':
        straight = ('R', 'Q')
        diagonal = ('B', 'Q')
    else:
        straight = ('r', 'q')
        diagonal = ('b', 'q')
    for dr, dc in _STRAIGHT_DIRS:
        nr, nc = r + dr, c + dc
        while 0 <= nr < 8 and 0 <= nc < 8:
            piece = board[nr][nc]
            if piece is not None:
                if piece in straight:
                    return True
                break  # any other piece blocks the ray
            nr += dr
            nc += dc
    for dr, dc in _DIAGONAL_DIRS:
        nr, nc = r + dr, c + dc
        while 0 <= nr < 8 and 0 <= nc < 8:
            piece = board[nr][nc]
            if piece is not None:
                if piece in diagonal:
                    return True
                break
            nr += dr
            nc += dc
    return False


def _board_with_king_at(board, active, r_through, c_through):
    """Copy of board with the side-to-move king removed from its start
    (file 4) and placed at (r_through, c_through), for through-check tests."""
    new = [row[:] for row in board]
    row = 0 if active == 'w' else 7
    king_char = 'K' if active == 'w' else 'k'
    new[row][4] = None
    new[r_through][c_through] = king_char
    return new


def _board_after_castle(board, active, wing):
    """Copy of board after a castling move is played."""
    new = [row[:] for row in board]
    row = 0 if active == 'w' else 7
    if wing == 'K':
        # king e->g, rook h->f
        new[row][6] = new[row][4]
        new[row][5] = new[row][7]
        new[row][7] = None
        new[row][4] = None
    else:
        # king e->c, rook a->d
        new[row][2] = new[row][4]
        new[row][3] = new[row][0]
        new[row][0] = None
        new[row][4] = None
    return new


def _gen_castling(board, active, rights, moves):
    """Append castling moves for the side to move."""
    white = active == 'w'
    row = 0 if white else 7
    king_char = 'K' if white else 'k'
    rook_char = 'R' if white else 'r'
    K = 'K' if white else 'k'
    Q = 'Q' if white else 'q'
    enemy = 'b' if white else 'w'
    base = 'e1' if white else 'e8'

    if board[row][4] != king_char:
        return

    for wing in ('K', 'Q'):
        right = K if wing == 'K' else Q
        if right not in rights:
            continue

        rook_col = 7 if wing == 'K' else 0
        through_col = 5 if wing == 'K' else 3
        land_col = 6 if wing == 'K' else 2

        # rook must be on its original square
        if board[row][rook_col] != rook_char:
            continue

        # all squares between the king and the rook must be empty
        lo, hi = (5, 7) if wing == 'K' else (0, 4)
        if any(board[row][c] is not None for c in range(lo, hi)):
            continue

        # the king may not castle out of check
        if _attacked_by(board, row, 4, enemy):
            continue

        # the king may not pass through an attacked square
        through_board = _board_with_king_at(board, active, row, through_col)
        if _attacked_by(through_board, row, through_col, enemy):
            continue

        # the king may not land on an attacked square
        if _attacked_by(_board_after_castle(board, active, wing), row, land_col, enemy):
            continue

        dest = _square_name(row, land_col)
        moves.append(base + dest)


def _generate_moves(board, active, rights=frozenset()):
    """All moves for the side to move (normal pieces + castling attempts)."""
    moves = []
    white = active == 'w'
    my = set('PNBRQK') if white else set('pnbrqk')
    enemy = set('pnbrqk') if white else set('PNBRQK')
    dr = 1 if white else -1          # pawn direction in rank index
    start_rank = 1 if white else 6   # white pawns start on rank 2 (index 1), black on rank 7 (index 6)

    for r in range(8):
        for c in range(8):
            ch = board[r][c]
            if ch is None or ch not in my:
                continue
            kind = ch.upper()
            src = _square_name(r, c)

            if kind == 'P':
                nr = r + dr
                if 0 <= nr < 8:
                    # one-square push
                    if board[nr][c] is None:
                        moves.append(src + _square_name(nr, c))
                        # double push from the starting rank
                        nr2 = r + 2 * dr
                        if r == start_rank and 0 <= nr2 < 8 and board[nr2][c] is None:
                            moves.append(src + _square_name(nr2, c))
                    # diagonal captures
                    for dc in (-1, 1):
                        nc = c + dc
                        if 0 <= nc < 8 and board[nr][nc] is not None and board[nr][nc] in enemy:
                            moves.append(src + _square_name(nr, nc))
                continue

            if kind == 'N' or kind == 'K':
                offsets = _KNIGHT_OFFSETS if kind == 'N' else _KING_OFFSETS
                for dr2, dc in offsets:
                    nr, nc = r + dr2, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] not in my:
                        moves.append(src + _square_name(nr, nc))
                continue

            # sliding pieces: B, R, Q
            if kind in ('B', 'R', 'Q'):
                dirs = []
                if kind in ('B', 'Q'):
                    dirs += _DIAGONAL_DIRS
                if kind in ('R', 'Q'):
                    dirs += _STRAIGHT_DIRS
                for dr2, dc in dirs:
                    nr, nc = r + dr2, c + dc
                    while 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if target is None:
                            moves.append(src + _square_name(nr, nc))
                        elif target in enemy:
                            moves.append(src + _square_name(nr, nc))
                            break
                        else:
                            break  # blocked by own piece
                        nr += dr2
                        nc += dc

    _gen_castling(board, active, rights, moves)
    return moves


def legal_moves(fen):
    """Every move for the side to move in `fen`, in UCI notation."""
    board, active = _parse_fen(fen)
    return _generate_moves(board, active, _parse_rights(fen))


def _update_rights(rights, active, mv, board, r2, c2):
    """Castling rights (set of 'K','Q','k','q') after `mv`."""
    new = set(rights)
    white = active == 'w'

    if mv[:2] in ('e1', 'e8'):
        # king moved: both rights for this color are lost
        if white:
            new -= {'K', 'Q'}
        else:
            new -= {'k', 'q'}
        return new

    # rook moved away from its original square
    r1, c1 = _parse_square(mv[:2])
    piece = board[r1][c1]
    if piece in ('R', 'r'):
        if (r1, c1) == (0, 0) and piece == 'R':
            new -= {'Q'}
        elif (r1, c1) == (0, 7) and piece == 'R':
            new -= {'K'}
        elif (r1, c1) == (7, 0) and piece == 'r':
            new -= {'q'}
        elif (r1, c1) == (7, 7) and piece == 'r':
            new -= {'k'}

    # enemy rook captured on its original square
    captured = board[r2][c2]
    if captured == 'R':
