        through_col = 5 if wing == 'K' else 3
        land_col = 6 if wing == 'K' else 2

        # rook must be on its original square
        if board[row][rook_col] != rook_char:
            continue

        # all squares between the king and the rook must be empty
        if wing == 'K':
            between = (5, 6)
        else:
            between = (1, 2, 3)
        if any(board[row][c] is not None for c in between):
            continue

        # the king may not castle out of check
        if _attacked_by(board, row, 4, enemy):
            continue

        # the king may not pass through an attacked square
        through_board = _board_with_king_at(board, active, row, through_col)
        if _attacked_by(through_board, row, through_col, enemy):
            continue

        # the king may not land on an attacked square
        if _attacked_by(_board_after_castle(board, active, wing), row, land_col, enemy):
            continue

        dest = _square_name(row, land_col)
        moves.append(base + dest)


def _generate_moves(board, active, rights=frozenset(), ep=None):
    """All pseudo-legal moves for the side to move."""
    moves = []
    white = active == 'w'
    my = set('PNBRQK') if white else set('pnbrqk')
    enemy = set('pnbrqk') if white else set('PNBRQK')
    dr = 1 if white else -1          # pawn direction in rank index
    start_rank = 1 if white else 6   # white pawns start on rank 2 (index 1), black on rank 7 (index 6)

    for r in range(8):
        for c in range(8):
            ch = board[r][c]
            if ch is None or ch not in my:
                continue
            kind = ch.upper()
            src = _square_name(r, c)

            if kind == 'P':
                nr = r + dr
                if 0 <= nr < 8:
                    promote = nr == (7 if white else 0)
                    # one-square push
                    if board[nr][c] is None:
                        if promote:
                            for p in _PROMOTIONS:
                                moves.append(src + _square_name(nr, c) + p)
                        else:
                            moves.append(src + _square_name(nr, c))
                        # double push from the starting rank
                        nr2 = r + 2 * dr
                        if r == start_rank and 0 <= nr2 < 8 and board[nr2][c] is None:
                            moves.append(src + _square_name(nr2, c))
                    # diagonal captures
                    for dc in (-1, 1):
                        nc = c + dc
                        if 0 <= nc < 8 and board[nr][nc] is not None and board[nr][nc] in enemy:
                            if promote:
                                for p in _PROMOTIONS:
                                    moves.append(src + _square_name(nr, nc) + p)
                            else:
                                moves.append(src + _square_name(nr, nc))

                # en passant
                if r == (4 if white else 3) and ep is not None:
                    ep_r, ep_c = ep
                    if 0 <= ep_r < 8 and ep_r == r + dr and abs(ep_c - c) == 1:
                        victim = board[r][ep_c]
                        if victim is not None and victim == ('p' if white else 'P'):
                            moves.append(src + _square_name(ep_r, ep_c))
                continue

            if kind == 'N' or kind == 'K':
                offsets = _KNIGHT_OFFSETS if kind == 'N' else _KING_OFFSETS
                for dr2, dc in offsets:
                    nr, nc = r + dr2, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8 and board[nr][nc] not in my:
                        moves.append(src + _square_name(nr, nc))
                continue

            # sliding pieces: B, R, Q
            if kind in ('B', 'R', 'Q'):
                dirs = []
                if kind in ('B', 'Q'):
                    dirs += _DIAGONAL_DIRS
                if kind in ('R', 'Q'):
                    dirs += _STRAIGHT_DIRS
                for dr2, dc in dirs:
                    nr, nc = r + dr2, c + dc
                    while 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if target is None:
                            moves.append(src + _square_name(nr, nc))
                        elif target in enemy:
                            moves.append(src + _square_name(nr, nc))
                            break
                        else:
                            break  # blocked by own piece
                        nr += dr2
                        nc += dc

    _gen_castling(board, active, rights, moves)
    return moves


def _apply_move(board, active, mv, ep=None):
    """Return the daughter board after applying (pseudo-legal) move `mv`."""
    white = active == 'w'
    r1, c1 = _parse_square(mv[:2])
    r2, c2 = _parse_square(mv[2:4])
    new_board = [row[:] for row in board]
    piece = board[r1][c1]
    is_pawn = piece is not None and piece.upper() == 'P'

    new_board[r2][c2] = piece
    new_board[r1][c1] = None

    # promotion: replace the pawn with the promoted piece
    if len(mv) == 5:
        new_board[r2][c2] = mv[4].upper() if white else mv[4].lower()

    # en passant: remove the captured pawn sitting beside the capturer
    if ep is not None and (r2, c2) == ep and is_pawn:
        victim = board[r1][c2]
        if victim is not None and victim.upper() == 'P' and (victim.isupper() != white):
            new_board[r1][c2] = None

    # castling: move the rook too
    rook_move = _CASTLING_ROOK_MOVES.get(mv)
    if rook_move is not None:
        (rf, rc), (rt, ct) = rook_move
        new_board[rt][ct] = new_board[rf][rc]
        new_board[rf][rc] = None

    return new_board


def _legal_moves(board, active, rights, ep):
    """Pseudo-legal moves minus any that leave our own king in check."""
    white = active == 'w'
    enemy = 'b' if white else 'w'
    king_char = 'K' if white else 'k'
    enemy_king = 'k' if white else 'K'
    legal = []
    for mv in _generate_moves(board, active, rights, ep):
        r2, c2 = _parse_square(mv[2:4])
        # the enemy king is never capturable
        if board[r2][c2] == enemy_king:
            continue
        new_board = _apply_move(board, active, mv, ep)
        king_pos = None
        for r in range(8):
            for c in range(8):
                if new_board[r][c] == king_char:
                    king_pos = (r, c)
                    break
            if king_pos is not None:
                break
        if king_pos is None:
            continue  # king should never disappear; be conservative
        if not _attacked_by(new_board, king_pos[0], king_pos[1], enemy):
            legal.append(mv)
    return legal


def legal_moves(fen):
    """Every legal move for the side to move in `fen`, in UCI notation."""
    board, active = _parse_fen(fen)
    return _legal_moves(board, active, _parse_rights(fen), _parse_ep(fen))


def _update_rights(rights, active, mv, board, r2, c2):
    """Castling rights (set of 'K','Q','k','q') after `mv`."""
    new = set(rights)
    white = active == 'w'

    if mv[:2] in ('e1', 'e8'):
        # king moved: both rights for this color are lost
        if white:
            new -= {'K', 'Q'}
        else:
            new -= {'k', 'q'}
        return new

    # rook moved away from its original square
    r1, c1 = _parse_square(mv[:2])
    piece = board[r1][c1]
    if piece in ('R', 'r'):
        if (r1, c1) == (0, 0) and piece == 'R':
            new -= {'Q'}
        elif (r1, c1) == (0, 7) and piece == 'R':
            new -= {'K'}
        elif (r1, c1) == (7, 0) and piece == 'r':
            new -= {'q'}
        elif (r1, c1) == (7, 7) and piece == 'r':
            new -= {'k'}

    # enemy rook captured on its original square
    captured = board[r2][c2]
    if captured == 'R':
        if (r2, c2) == (0, 0):
            new -= {'Q'}
        elif (r2, c2) == (0, 7):
            new -= {'K'}
    elif captured == 'r':
        if (r2, c2) == (7, 0):
            new -= {'q'}
        elif (r2, c2) == (7, 7):
            new -= {'k'}

    return new


_CASTLING_ROOK_MOVES = {
    'e1g1': ((0, 7), (0, 5)),
    'e1c1': ((0, 0), (0, 3)),
    'e8g8': ((7, 7), (7, 5)),
    'e8c8': ((7, 0), (7, 3)),
}


def _perft_board(board, active, depth, rights, ep=None):
    if depth == 0:
        return 1
    total = 0
    white = active == 'w'
    dr = 1 if white else -1
    for mv in _legal_moves(board, active, rights, ep):
        r1, c1 = _parse_square(mv[:2])
        r2, c2 = _parse_square(mv[2:4])
        new_board = _apply_move(board, active, mv, ep)

        # next en passant target: valid only right after a double push
        piece = board[r1][c1]
        is_pawn = piece is not None and piece.upper() == 'P'
        next_ep = None
        if is_pawn and abs(r2 - r1) == 2:
            next_ep = (r1 + dr, c1)

        new_rights = _update_rights(rights, active, mv, board, r2, c2)
        next_active = 'b' if active == 'w' else 'w'
        total += _perft_board(new_board, next_active, depth - 1, new_rights, next_ep)
    return total


def perft(fen, depth):
    """Number of legal leaf nodes at `depth` plies (perft(0) == 1)."""
    if depth < 0:
        raise ValueError('depth must be >= 0')
    board, active = _parse_fen(fen)
    return _perft_board(board, active, depth, _parse_rights(fen), _parse_ep(fen))
